/*
CONTROL DE RESPUESTAJQUERE
*/
function respuestaJqueryAjax(Respuesta){
	if (Respuesta == "UI") {
    ir_a_login()
	ver_vetana_informativa("USUARIO INCORRECTO VUELVA A INICIAR SESION...")
	return false;
	}
    if (Respuesta == "NI") {
	ver_vetana_informativa("NO TIENES PERMISO PARA CONTINUA", "", "error")
	return false;
    }
	if (Respuesta == "CI") {
	ver_vetana_informativa("CONTRASEÑA O USUARIO INVÁLIDOS")
	return false;
    }
	if (Respuesta == "CAMPOSVACIOS") {
    ver_vetana_informativa("FALTO INGRESAR ALGUNOS CAMPOS...")
	return false;
    }
	if(Respuesta == "EX") {
    ver_vetana_informativa("YA EXISTE UNA CLIENTE SIMILAR...")
	return false;
    }
	if (Respuesta == "exito") {
	return true;
    }
	
	if(Respuesta == "EXPR") {
    ver_vetana_informativa("YA EXISTE UN PRODUCTO SIMILAR...")
	return false;
    }
	
	if(Respuesta == "NoExiste") {
    ver_vetana_informativa("EL REGISTRO NO EXISTE", "", "error")
	return false;
    }
}
/*
Control de acceso 
*/
function controlacceso(frm,accion){
	if (userid == '2') return true;
	if(permisoAccesoUser(frm,accion)==false){
		ver_vetana_informativa("NO TIENES PERMISO PARA ACCEDER")
		  return false;
	}else{
		return true;
	}
}



function controlacceso2(frm,accion){
	if (userid == '2') return true;
	if(permisoAccesoUser(frm,accion)==false){
		return false;
	}else{
		return true;
	}
}

function obtenerAccesoUser(frm){
	if(typeof accesosuser === "undefined" || !accesosuser){
		return null;
	}
	if(accesosuser[frm] != undefined){
		return accesosuser[frm];
	}
	var codigoBuscado = String(frm).trim().toUpperCase();
	for(var codigo in accesosuser){
		if(Object.prototype.hasOwnProperty.call(accesosuser, codigo) && String(codigo).trim().toUpperCase() == codigoBuscado){
			return accesosuser[codigo];
		}
	}
	return null;
}

function permisoAccesoUser(frm,accion){
	var acceso = obtenerAccesoUser(frm);
	if(!acceso || acceso[accion] == undefined){
		return false;
	}
	return String(acceso[accion]).trim().toUpperCase() == "SI";
}

/*
GUARDAR ARCHIVOS LOG
*/
function GuardarArchivosLog(errorlog)
{
	var f = new Date();
	var dia = f.getDate()
	if (dia < 10) {
		dia = "0" + dia;
	}
	var mes = f.getMonth() + 1
	if (mes < 10) {
		mes = "0" + mes;
	}
	var hora = f.getHours() 
    var minuto = f.getMinutes() 
    var segundo = f.getSeconds() 
	var archivoname = f.getFullYear() + "_" + mes + "_" + dia+"_"+hora+"_"+minuto+"_"+segundo;
	var a = document.createElement("a");
    document.body.appendChild(a);
    a.style = "display: none";
    var blob = new File([errorlog], "log_"+archivoname+".txt");
    url = window.URL.createObjectURL(blob);
    a.href = url;
    a.download = blob.name;
    a.click();
    window.URL.revokeObjectURL(url);
    
}



